import sys

def parse_and_sum(s):
    total_cents = 0
    i = 0
    n = len(s)

    while i < n:
        if s[i].isalpha():
            while i < n and s[i].isalpha():
                i += 1
        else:
            j = i
            while j < n and (s[j].isdigit() or s[j] == '.'):
                j += 1
            price_str = s[i:j]
            total_cents += parse_price(price_str)
            i = j

    return total_cents

def parse_price(price_str):
    parts = price_str.split('.')
    if len(parts) == 1:
        dollars = int(parts[0])
        cents = 0
    else:
        dollars_part = parts[0]
        cents_part = parts[1]
        dollars = int(dollars_part) if dollars_part else 0
        cents = int(cents_part)
    return dollars * 100 + cents

def format_price(total_cents):
    dollars = total_cents // 100
    cents = total_cents % 100

    dollars_str = str(dollars)
    formatted_dollars = []
    for i in range(0, len(dollars_str), 3):
        chunk = dollars_str[i:i+3]
        if formatted_dollars:
            formatted_dollars.append('.')
        formatted_dollars.append(chunk)

    if cents > 0:
        return ''.join(formatted_dollars) + '.' + f"{cents:02d}"
    else:
        return ''.join(formatted_dollars)

def main():
    s = sys.stdin.readline().strip()
    total_cents = parse_and_sum(s)
    print(format_price(total_cents))

if __name__ == "__main__":
    main()
